import { GoogleGenAI, Type } from "@google/genai";
import { EmployeeSummary } from "../types";

// وظيفة التدقيق السريع لموظف واحد - تم تحسينها لتكون أكثر دقة واختصاراً
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
  const faultyShifts = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .slice(0, 10) // نأخذ أول 10 أيام خلل فقط لتقليل التوكنز
    .map(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      const missing = required.filter(r => !present.includes(r));
      return `${s.shift_date}: نقص [${missing.join('، ')}]`;
    });

  if (faultyShifts.length === 0) return "✨ السجل كامل ومنضبط تماماً.";

  const prompt = `دقق سجل الموظف (${employee.name}) ذو الرقم (${employee.id}).
  البيانات المرصودة:
  ${faultyShifts.join('\n')}
  المطلوب: قدم ملخصاً إدارياً قصيراً جداً للنواقص بصيغة نقاط، واقترح سبباً محتملاً (نسيان، خلل فني، إلخ).`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2, maxOutputTokens: 300 }
    });
    return response.text?.trim() || "تم تحليل البيانات بنجاح.";
  } catch (error) {
    console.error("AI Error:", error);
    return "⚠️ تعذر توليد الملخص الفردي حالياً.";
  }
};

// وظيفة تحليل النواقص لكل الموظفين دفعة واحدة - ذكاء اصطناعي مجمع
export const analyzeGlobalDeficienciesAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyEmployees = employees.filter(e => !e.isEligible);
  if (faultyEmployees.length === 0) return "✅ لا توجد نواقص في كامل السجل. جميع الموظفين ملتزمون.";

  // تلخيص البيانات محلياً لتقليل التوكنز
  const stats = {
    total: employees.length,
    faultyCount: faultyEmployees.length,
    commonIssues: {} as Record<string, number>
  };

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];

  faultyEmployees.forEach(e => {
    e.shifts.filter(s => s.status === 'ناقصة').forEach(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      required.forEach(r => {
        if (!present.includes(r)) {
          stats.commonIssues[r] = (stats.commonIssues[r] || 0) + 1;
        }
      });
    });
  });

  const prompt = `أنت مدقق أنظمة حضور وانصراف خبير.
  إليك ملخص إحصائي لنواقص الموظفين في الشركة:
  - إجمالي الموظفين: ${stats.total}
  - عدد الموظفين الذين لديهم نواقص: ${stats.faultyCount}
  - توزيع النواقص حسب الفترات: ${JSON.stringify(stats.commonIssues)}

  المطلوب: كتابة تقرير إداري رفيع المستوى يلخص حالة الانضباط العامة، يبرز أكثر فترة فيها خلل، ويقدم نصيحة للقيادة لتحسين الالتزام. كن مهنياً ومختصراً جداً.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.3, maxOutputTokens: 500 }
    });
    return response.text?.trim() || "التقرير الإجمالي جاهز للمراجعة.";
  } catch (error) {
    return "⚠️ فشل تحليل البيانات الجماعية.";
  }
};

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const faultyDates = employee.shifts.filter(s => s.status === 'ناقصة').slice(0, 5).map(s => s.shift_date);
  if (faultyDates.length === 0) return "✅ السجل التقني سليم.";

  const prompt = `دقق تقنياً: ID:${employee.id}. خلل في:${faultyDates.join(',')}. هل السلوك يوحي بتلاعب أم مجرد نسيان؟ رد بكلمتين فقط.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0, maxOutputTokens: 20 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle,
  FileSearch, BarChart3
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeGlobalDeficienciesAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [globalReport, setGlobalReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setGlobalReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateGlobalReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeGlobalDeficienciesAI(employees);
      setGlobalReport(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      <aside className={`fixed inset-y-0 right-0 z-50 w-64 bg-[#0a0f1e] text-white transition-all duration-300 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-6">
          <div className="flex items-center gap-3 mb-10 group cursor-pointer">
            <div className="p-2.5 bg-gradient-to-tr from-indigo-600 to-violet-500 rounded-[1.25rem] shadow-lg shadow-indigo-500/20 group-hover:rotate-6 transition-transform">
              <ShieldCheck size={24} className="text-white" />
            </div>
            <div>
              <h1 className="font-extrabold text-lg text-white tracking-tight">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[9px] text-slate-500 font-bold uppercase tracking-widest mt-0.5 opacity-60">نظام التدقيق الذكي</p>
            </div>
          </div>
          <nav className="space-y-1.5 flex-1">
            <SidebarLink icon={<LayoutDashboard size={18}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={18}/>} label="قائمة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<BarChart3 size={18}/>} label="تقرير النواقص الشامل" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>
          <div className="mt-auto pt-6 border-t border-slate-800">
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-xs text-white shadow-xl shadow-indigo-600/10 active:scale-95 group">
              <FileUp size={20} className="group-hover:-translate-y-1 transition-transform" />
              <span>رفع سجل جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-100 px-6 py-4 flex items-center justify-between shrink-0 z-20">
          <div className="flex items-center gap-4 flex-1">
            <button className="lg:hidden p-2 text-slate-500 hover:bg-slate-50 rounded-xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={22} />
            </button>
            <div className="relative w-full max-w-md">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={16} />
              <input 
                type="text" 
                placeholder="ابحث عن موظف..." 
                className="w-full bg-slate-50 border border-slate-200 rounded-xl pr-11 pl-4 py-2.5 text-xs outline-none focus:ring-4 focus:ring-indigo-500/5 focus:border-indigo-400 transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateGlobalReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-2.5 px-6 py-2.5 bg-slate-900 text-white rounded-xl text-[10px] font-black hover:bg-indigo-600 transition-all active:scale-95 disabled:opacity-20 shadow-lg shadow-slate-900/10"
          >
            {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={16} className="animate-spin" /> : <FileSearch size={16} className="text-indigo-400" />}
            <span className="hidden sm:inline">ملخص النواقص المكتشفة (للكل)</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-4 lg:p-8 space-y-8 bg-[#f8fafc] custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-700 space-y-8 max-w-6xl mx-auto">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatBox title="إجمالي الكادر" value={stats.totalEmployees} icon={<Users size={20}/>} color="indigo" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={20}/>} color="emerald" />
                    <StatBox title="سجلات البصمة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={20}/>} color="amber" />
                  </div>
                  <div>
                    <div className="flex items-center justify-between mb-6">
                      <SectionTitle icon={<Activity size={18}/>} title="نظرة سريعة على الموظفين" />
                    </div>
                    <EmployeeListSection employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 space-y-6 max-w-6xl mx-auto">
              <SectionTitle icon={<Users size={18}/>} title="سجل الموظفين والتدقيق الذكي" />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-4xl mx-auto space-y-8">
              <div className="bg-gradient-to-br from-[#0a0f1e] to-slate-900 text-white p-12 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                <div className="relative z-10">
                  <div className="flex items-center gap-5 mb-10">
                     <div className="p-4 bg-indigo-500/10 rounded-[2rem] border border-white/5">
                        <BarChart3 className="text-indigo-400" size={36} />
                     </div>
                     <div>
                        <h2 className="text-3xl font-black tracking-tight">تقرير رادار النواقص</h2>
                        <p className="text-slate-500 text-sm font-medium mt-1 uppercase tracking-widest">إحصائيات المؤسسة بالذكاء الاصطناعي</p>
                     </div>
                  </div>
                  <div className="bg-white/5 backdrop-blur-xl p-8 rounded-[2.5rem] border border-white/10 mb-10 font-bold text-indigo-100/90 leading-relaxed shadow-inner">
                    {isAnalyzing ? (
                      <div className="flex items-center gap-4 py-10 justify-center">
                        <RefreshCcw size={24} className="animate-spin text-indigo-400" />
                        <span className="text-lg">جاري تلخيص النواقص عبر Gemini AI...</span>
                      </div>
                    ) : globalReport ? (
                      <div className="whitespace-pre-line text-lg leading-relaxed">{globalReport}</div>
                    ) : (
                      <div className="text-center py-10 opacity-50">اضغط على زر "ملخص النواقص المكتشفة" لبدء التحليل الجماعي.</div>
                    )}
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-3 gap-6">
                     <IntegrityMetric label="مكررات معالجة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} />
                     <IntegrityMetric label="موظفين غير منضبطين" value={employees.filter(e => !e.isEligible).length} />
                     <IntegrityMetric label="نسبة النجاح" value={`${(stats?.completionRate || 0)}%`} />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- UI Components --- */

