     <div className="text-indigo-300 text-[10px] font-black uppercase mb-2 tracking-widest opacity-70">{label}</div>
     <div className="text-2xl font-black text-white">{value}</div>
  </div>
);

const SectionTitle = ({ icon, title }: any) => (
