const EmployeeListSection = ({ employees, isAnalyzing }: { employees: EmployeeSummary[], isAnalyzing: boolean }) => (
  <div className="space-y-5 animate-in fade-in duration-700">
    {isAnalyzing ? (
      <div className="flex flex-col items-center py-20 bg-white rounded-[3rem] border border-slate-100 shadow-sm">
        <RefreshCcw className="animate-spin text-indigo-600 mb-6" size={40} />
        <p className="text-[10px] font-black text-slate-400 tracking-[0.4em] uppercase">جاري معالجة البيانات</p>
      </div>
