    indigo: "from-indigo-600 to-violet-600 shadow-indigo-200",
    emerald: "from-emerald-600 to-teal-500 shadow-emerald-200",
    amber: "from-amber-500 to-orange-400 shadow-amber-200"
  };
  return (
    <div className={`bg-gradient-to-br ${themes[color]} p-7 rounded-[2.5rem] text-white shadow-xl relative overflow-hidden group transition-all hover:scale-[1.02] border border-white/10`}>
       <div className="relative flex justify-between items-center">
          <div>
            <p className="text-[10px] font-black uppercase opacity-70 mb-1 tracking-widest">{title}</p>
            <h4 className="text-3xl font-black tracking-tight">{value}</h4>
          </div>
          <div className="p-4 bg-white/20 backdrop-blur-md rounded-[1.5rem] border border-white/20 shadow-lg group-hover:rotate-6 transition-transform">
            {icon}
          </div>
       </div>
    </div>
