};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3.5 px-6 py-4 rounded-[1.25rem] transition-all font-bold text-sm ${active ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-600/20 translate-x-1' : 'text-slate-400 hover:bg-white/5 hover:text-slate-200'}`}>
    {icon} <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (auditResult) return;
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (detailedSummary) {
      setIsExpanded(true); // إذا كان موجوداً، فقط افتح القائمة
      return;
    }
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
      setIsExpanded(true); // افتح القائمة تلقائياً لمشاهدة النتيجة
    } catch (err) {
      setDetailedSummary("⚠️ فشل التوليد.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const copyToClipboard = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (detailedSummary) {
      navigator.clipboard.writeText(detailedSummary);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-[2.5rem] transition-all duration-500 overflow-hidden group/main ${isExpanded ? 'shadow-2xl shadow-slate-200 ring-4 ring-indigo-50 border-transparent' : 'shadow-sm border border-slate-100 hover:border-indigo-100 hover:shadow-lg'}`}>
      <div 
        className={`p-6 flex flex-col lg:flex-row items-center gap-8 cursor-pointer relative transition-all duration-500 ${isAllComplete ? 'bg-gradient-to-l from-emerald-50/20 to-transparent' : 'bg-gradient-to-l from-rose-50/20 to-transparent'}`} 
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-5 min-w-[340px]">
          <div className="relative group-hover/main:scale-105 transition-all duration-500">
            <div className={`w-16 h-16 rounded-[1.75rem] flex items-center justify-center font-black text-2xl shadow-xl transition-all ${isAllComplete ? 'bg-gradient-to-br from-emerald-500 to-emerald-600 text-white shadow-emerald-200/50' : 'bg-gradient-to-br from-rose-500 to-rose-600 text-white shadow-rose-200/50'}`}>
              {employee.name.charAt(0)}
            </div>
            <div className={`absolute -bottom-1 -right-1 bg-white p-1.5 rounded-full shadow-lg border border-slate-50`}>
               {isAllComplete ? <CheckCircle2 size={16} className="text-emerald-500" /> : <ShieldAlert size={16} className="text-rose-500" />}
            </div>
          </div>
          <div className="space-y-1">
            <h3 className="font-extrabold text-xl text-slate-900 group-hover/main:text-indigo-600 transition-colors tracking-tight truncate max-w-[260px] leading-tight">{employee.name}</h3>
            <div className="flex items-center gap-2.5">
