const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-6 rounded-[2.5rem] border bg-white flex flex-col transition-all duration-300 hover:shadow-2xl hover:-translate-y-1.5 ${isComplete ? 'border-slate-100 shadow-sm' : 'border-rose-100 bg-rose-50/5 shadow-md shadow-rose-500/5'}`}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3.5">
          <div className={`p-3 rounded-2xl shadow-sm ${isComplete ? 'bg-indigo-50 text-indigo-600' : 'bg-rose-50 text-rose-600'}`}>
            <Calendar size={18} />
          </div>
          <div className="flex flex-col">
             <span className="text-[14px] font-black text-slate-800 tracking-tight">{shift.shift_date}</span>
             <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-0.5">تاريخ الوردية</span>
          </div>
        </div>
        <span className={`px-4 py-2 rounded-2xl text-[10px] font-black uppercase shadow-lg transition-all ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200/50' : 'bg-rose-500 text-white shadow-rose-200/50'}`}>
          {shift.status}
        </span>
      </div>
      <div className="space-y-4 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';
          return (
            <div key={idx} className={`flex flex-col gap-2.5 pr-6 relative py-4 px-5 rounded-[2rem] transition-all border ${
              isExit ? 'bg-emerald-50/40 border-emerald-100/30' : isEntry ? 'bg-indigo-50/40 border-indigo-100/30' : 'bg-slate-50/80 border-slate-100'
            }`}>
               <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-2 h-8 rounded-full ${
                 isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : isEntry ? 'bg-indigo-500' : 'bg-slate-300'
               }`}></div>
               <div className="flex items-center justify-between">
                  <span className={`text-[11px] font-black uppercase tracking-widest flex items-center gap-3 ${
                    isExit ? 'text-emerald-700' : isEntry ? 'text-indigo-700' : 'text-slate-500'
                  }`}>
                    {isExit && <LogOut size={16} className="opacity-80" />}
                    {isEntry && <LogIn size={16} className="opacity-80" />}
                    {group.period}
                  </span>
               </div>
               <div className="flex flex-wrap gap-2.5">
                 {group.punches.map((p, pIdx) => (
                   <span key={pIdx} className={`px-4 py-2 rounded-[1.25rem] border text-[12px] font-black flex items-center gap-2.5 transition-all group/punch ${
                      p.is_duplicate ? 'bg-rose-50 border-rose-100 text-rose-300 line-through opacity-60' : 'bg-white border-slate-100 text-slate-700 shadow-sm hover:shadow-md'
                    }`}>
                     <Clock size={14} className="opacity-30 group-hover/punch:opacity-80 transition-opacity" />
                     {p.time}
                   </span>
                 ))}
               </div>
            </div>
          );
        })}
        {!isComplete && (
           <div className="flex items-center gap-3 text-rose-400 text-[11px] font-black px-5 py-4 bg-rose-50/50 rounded-[1.75rem] border border-dashed border-rose-200">
              <ShieldAlert size={18} />
              <span className="tracking-tight">نقص في تسلسل البصمات الإلزامي</span>
           </div>
        )}
      </div>
    </div>
  );
};

