import { GoogleGenAI, Type } from "@google/genai";
import { EmployeeSummary } from "../types";

// وظيفة التدقيق السريع لموظف واحد - زيادة حدود التوكن وتحسين التحليل
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
  const faultyShifts = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .slice(0, 15) // زيادة العينة للتحليل
    .map(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      const missing = required.filter(r => !present.includes(r));
      return `- التاريخ ${s.shift_date}: ينقصه (${missing.join(' و ')})`;
    });

  if (faultyShifts.length === 0) return "✨ السجل نظيف تماماً، الموظف يظهر التزاماً مثالياً بكافة فترات البصمة.";

  const prompt = `أنت خبير تدقيق إداري. حلل سجل النواقص للموظف (${employee.name}):
  البيانات:
  ${faultyShifts.join('\n')}

  المطلوب:
  1. ملخص تنفيذي للحالة.
  2. تحديد "النمط" (مثلاً: هل النقص دائماً في الخروج؟ أو في الفترة المسائية؟).
  3. التوصية الإدارية المناسبة (تنبيه، مراجعة تقنية، أو شكر على الانضباط العام).
  اجعل الرد مهنياً، منظماً، وباللغة العربية الفصحى، ولا تتوقف قبل إتمام التوصية.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.4, 
        maxOutputTokens: 1000, // زيادة كبيرة لضمان عدم الانقطاع
        topP: 0.8 
      }
    });
    return response.text?.trim() || "تعذر صياغة التقرير، يرجى المحاولة مرة أخرى.";
  } catch (error) {
    console.error("AI Error:", error);
    return "⚠️ حدث خطأ أثناء الاتصال بالذكاء الاصطناعي. تأكد من جودة الاتصال.";
  }
};

// وظيفة تحليل النواقص لكل الموظفين - تقرير قيادي شامل
export const analyzeGlobalDeficienciesAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyEmployees = employees.filter(e => !e.isEligible);
  if (faultyEmployees.length === 0) return "✅ إنجاز استثنائي: كافة الكادر الوظيفي ملتزم بنظام البصمة بنسبة 100%.";

  const stats = {
    total: employees.length,
    faultyCount: faultyEmployees.length,
    commonIssues: {} as Record<string, number>,
    topFaulty: faultyEmployees.slice(0, 3).map(e => e.name)
  };

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
  faultyEmployees.forEach(e => {
    e.shifts.filter(s => s.status === 'ناقصة').forEach(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      required.forEach(r => {
        if (!present.includes(r)) {
          stats.commonIssues[r] = (stats.commonIssues[r] || 0) + 1;
        }
      });
    });
  });

  const prompt = `بصفتك كبير مدققي الأنظمة، اكتب تقريراً استراتيجياً للمدير العام بناءً على هذه الإحصائيات:
  - الكادر الإجمالي: ${stats.total}
  - عدد الموظفين غير المنضبطين: ${stats.faultyCount}
  - توزيع النواقص: ${JSON.stringify(stats.commonIssues)}
  - عينة من الأسماء المتكررة نواقصهم: ${stats.topFaulty.join('، ')}

  المطلوب تقرير مفصل يتضمن:
  - تحليل الفجوة (Gap Analysis) لأكثر الفترات خللاً.
  - تقييم المخاطر الإدارية.
  - خطة عمل مقترحة (Action Plan).
  اجعل الأسلوب رفيع المستوى واكتب التقرير كاملاً دون اختصار مخل.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.5, 
        maxOutputTokens: 2000 // كافٍ لتقرير إداري طويل
      }
    });
    return response.text?.trim() || "التقرير قيد المعالجة...";
  } catch (error) {
    return "⚠️ فشل توليد التقرير الشامل. يرجى مراجعة حصة الاستخدام (Quota).";
  }
};

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const faultyDates = employee.shifts.filter(s => s.status === 'ناقصة').slice(0, 5).map(s => s.shift_date);
  if (faultyDates.length === 0) return "🛡️ السجل التقني للموظف محصن من أي ثغرات.";

  const prompt = `دقق تقنياً خلفية البصمات لـ ${employee.name}. التواريخ المصابة: ${faultyDates.join(',')}. هل المؤشرات تشير لخلل في الجهاز أم إهمال بشري؟ أجب بذكاء واختصار.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2, maxOutputTokens: 100 }
    });
    return response.text?.trim() || "التدقيق اكتمل.";
  } catch (error) {
    return "⚠️ تعذر التدقيق.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle,
  FileSearch, BarChart3, Zap, Send
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeGlobalDeficienciesAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [globalReport, setGlobalReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setGlobalReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف. تأكد من أن الأعمدة مطابقة للمعايير.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateGlobalReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setGlobalReport(null);
    try {
      const result = await analyzeGlobalDeficienciesAI(employees);
      setGlobalReport(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#050914] text-white transition-all duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="flex items-center gap-4 mb-12 group cursor-pointer">
            <div className="p-3 bg-gradient-to-br from-indigo-500 via-indigo-600 to-violet-700 rounded-2xl shadow-xl shadow-indigo-500/30 group-hover:scale-110 transition-transform">
              <Zap size={24} className="text-white fill-current" />
            </div>
            <div>
              <h1 className="font-black text-xl text-white tracking-tight leading-none">بصمتي <span className="text-indigo-400">AI</span></h1>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-1 opacity-70">المساعد الذكي</p>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={20}/>} label="الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<BarChart3 size={20}/>} label="رادار النواقص" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto">
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-gradient-to-r from-indigo-600 to-violet-600 rounded-2xl cursor-pointer hover:shadow-2xl hover:shadow-indigo-500/40 transition-all font-black text-sm text-white active:scale-95 group">
              <FileUp size={20} className="group-hover:-translate-y-1 transition-transform" />
              <span>تحديث البيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Header */}
        <header className="bg-white/70 backdrop-blur-xl border-b border-slate-100 px-8 py-5 flex items-center justify-between shrink-0 z-20">
