                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <div className="flex items-center gap-3">
             <button 
                onClick={generateGlobalReport}
                disabled={employees.length === 0 || isAnalyzing}
                className="relative overflow-hidden group flex items-center gap-2.5 px-8 py-3 bg-slate-900 text-white rounded-[1.25rem] text-xs font-black hover:bg-indigo-600 transition-all disabled:opacity-30 shadow-xl shadow-slate-900/10 active:scale-95"
              >
                {isAnalyzing ? <RefreshCcw size={18} className="animate-spin" /> : <Sparkles size={18} className="text-indigo-400" />}
                <span>تحليل الأداء العام</span>
              </button>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-6 lg:p-10 space-y-10 bg-[#f8fafc] custom-scrollbar pb-40">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-1000 slide-in-from-bottom-5 max-w-7xl mx-auto space-y-10">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <StatCard title="إجمالي الكادر" value={stats.totalEmployees} icon={<Users size={24}/>} color="indigo" />
                    <StatCard title="مستوى الالتزام" value={`${stats.completionRate}%`} icon={<Target size={24}/>} color="emerald" />
                    <StatCard title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={24}/>} color="amber" />
                  </div>
                  <div>
                    <SectionHeader icon={<Activity size={22}/>} title="أحدث النشاطات" subtitle="نظرة على آخر 10 موظفين تم معالجتهم" />
                    <EmployeeListSection employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 max-w-7xl mx-auto space-y-8">
              <SectionHeader icon={<Users size={22}/>} title="قاعدة بيانات الموظفين" subtitle={`تم العثور على ${filteredEmployees.length} سجل`} />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in zoom-in-95 duration-700 max-w-5xl mx-auto">
              <div className="bg-white rounded-[3.5rem] shadow-2xl shadow-indigo-500/5 border border-slate-100 overflow-hidden relative">
                <div className="absolute top-0 left-0 w-full h-2.5 bg-gradient-to-r from-indigo-500 via-violet-500 to-indigo-600"></div>
                <div className="p-12">
                   <div className="flex flex-col md:flex-row md:items-center justify-between gap-8 mb-12">
                      <div className="flex items-center gap-6">
                         <div className="w-20 h-20 bg-indigo-50 rounded-[2.5rem] flex items-center justify-center border border-indigo-100 shadow-inner">
                            <BarChart3 size={36} className="text-indigo-600" />
                         </div>
                         <div>
                            <h2 className="text-3xl font-black text-slate-900 tracking-tight">تقرير رادار النواقص</h2>
                            <p className="text-slate-400 font-bold text-sm mt-1">تحليل شامل ومعمق بواسطة Gemini 3 Flash</p>
                         </div>
                      </div>
                      <button 
                        onClick={generateGlobalReport}
                        className="flex items-center gap-3 px-8 py-4 bg-indigo-50 text-indigo-600 rounded-2xl font-black text-sm hover:bg-indigo-100 transition-all border border-indigo-200/50"
                      >
                         <RefreshCcw size={18} className={isAnalyzing ? 'animate-spin' : ''} />
                         إعادة توليد التقرير
                      </button>
                   </div>

                   <div className="bg-slate-50/50 rounded-[3rem] p-10 border border-slate-100 relative group">
                      <div className="absolute top-6 left-6 opacity-0 group-hover:opacity-100 transition-opacity">
                        <button 
                          onClick={() => globalReport && navigator.clipboard.writeText(globalReport)}
                          className="p-3 bg-white text-slate-400 hover:text-indigo-600 rounded-xl border border-slate-200 shadow-sm"
                        >
                          <Copy size={20} />
                        </button>
                      </div>

                      {isAnalyzing ? (
                        <div className="py-24 flex flex-col items-center gap-6">
                           <div className="relative">
                              <div className="w-16 h-16 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin"></div>
                              <Sparkles className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 text-indigo-400 animate-pulse" size={24} />
                           </div>
                           <p className="text-slate-500 font-black animate-pulse tracking-widest uppercase text-xs">جاري التفكير وصياغة التقرير...</p>
                        </div>
                      ) : globalReport ? (
                        <div className="prose prose-indigo max-w-none">
                           <div className="whitespace-pre-line text-lg text-slate-700 leading-relaxed font-medium">
                              {globalReport}
                           </div>
                        </div>
                      ) : (
                        <div className="py-24 text-center">
                           <BrainCircuit size={64} className="mx-auto text-slate-200 mb-6" />
                           <p className="text-slate-400 font-bold">لا يوجد تقرير حالياً. ابدأ التحليل من الأعلى.</p>
                        </div>
                      )}
                   </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Visual Components --- */

