    amber: "from-amber-500 to-orange-500 shadow-amber-100"
  };
  return (
    <div className={`bg-gradient-to-br ${themes[color]} p-8 rounded-[3rem] text-white shadow-2xl relative overflow-hidden group transition-all hover:-translate-y-1.5 border border-white/10`}>
       <div className="absolute -right-6 -bottom-6 opacity-10 group-hover:scale-150 transition-transform duration-700">
