    {icon} <span>{label}</span>
  </button>
);

const EmployeeCard: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (auditResult) return;
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ في التدقيق.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const generateAIAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    setDetailedSummary(null); // إعادة التصفير للتأكد من التحميل الجديد
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
      setIsExpanded(true);
    } catch (err) {
      setDetailedSummary("⚠️ تعذر توليد الملخص.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const copyToClipboard = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (detailedSummary) {
      navigator.clipboard.writeText(detailedSummary);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const isAllComplete = employee.isEligible;

  return (
    <div className={`bg-white rounded-[3rem] transition-all duration-700 overflow-hidden group/main ${isExpanded ? 'shadow-2xl shadow-indigo-500/5 ring-1 ring-slate-100 border-indigo-200' : 'shadow-sm border border-slate-100 hover:border-indigo-100 hover:shadow-lg hover:-translate-y-1'}`}>
      <div 
        className={`p-7 flex flex-col lg:flex-row items-center gap-10 cursor-pointer relative transition-all duration-500 ${isAllComplete ? 'bg-gradient-to-l from-emerald-50/10 to-transparent' : 'bg-gradient-to-l from-rose-50/10 to-transparent'}`} 
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-6 min-w-[360px]">
          <div className="relative">
            <div className={`w-20 h-20 rounded-[2.25rem] flex items-center justify-center font-black text-3xl shadow-xl transition-all duration-500 group-hover/main:rotate-6 ${isAllComplete ? 'bg-gradient-to-br from-emerald-500 to-emerald-600 text-white' : 'bg-gradient-to-br from-rose-500 to-rose-600 text-white'}`}>
              {employee.name.charAt(0)}
            </div>
            <div className="absolute -bottom-1 -right-1 bg-white p-2 rounded-full shadow-lg border border-slate-50">
               {isAllComplete ? <CheckCircle2 size={18} className="text-emerald-500" /> : <ShieldAlert size={18} className="text-rose-500" />}
            </div>
          </div>
          <div className="space-y-1.5">
            <h3 className="font-black text-2xl text-slate-900 group-hover/main:text-indigo-600 transition-colors tracking-tight leading-none">{employee.name}</h3>
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black text-slate-400 bg-slate-100 px-3 py-1.5 rounded-xl border border-slate-200/50 uppercase tracking-[0.2em]">رقم: {employee.id}</span>
              <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest border transition-all ${employee.isEligible ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                {employee.isEligible ? 'سجل مكتمل' : 'نواقص مكتشفة'}
              </span>
            </div>
          </div>
        </div>

        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50/50 backdrop-blur-md rounded-[2.5rem] py-6 px-12 border border-slate-200/40 gap-8 shadow-inner hover:bg-white transition-all duration-500">
          <StatMini label="بصمات" value={employee.totalPunches} icon={<Fingerprint size={14} className="text-amber-500"/>} />
          <StatMini label="نوبات" value={employee.shifts.length} icon={<Timer size={14} className="text-indigo-500"/>} />
          <StatMini label="أداء" value={`${employee.performanceScore}%`} icon={<TrendingUp size={14} className="text-violet-500"/>} />
          <StatMini label="معدل" value={`${employee.completionRate}%`} icon={<Target size={14} className="text-emerald-500"/>} />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex bg-white p-2 rounded-[2rem] border border-slate-100 shadow-sm">
             <button 
                onClick={generateAIAudit} 
                disabled={loadingSummary} 
                className={`flex items-center justify-center w-14 h-14 rounded-[1.5rem] transition-all active:scale-90 disabled:opacity-40 ${detailedSummary ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400 hover:bg-indigo-50 hover:text-indigo-600'}`}
                title="توليد تحليل ذكي"
              >
                {loadingSummary ? <RefreshCcw size={22} className="animate-spin" /> : <Sparkles size={24} />}
              </button>
              <button 
                onClick={runSmartAudit} 
                disabled={loadingAudit} 
                className="flex items-center justify-center w-14 h-14 rounded-[1.5rem] hover:bg-slate-900 hover:text-white text-slate-400 transition-all active:scale-90 disabled:opacity-40"
                title="تدقيق تقني"
              >
                {loadingAudit ? <RefreshCcw size={22} className="animate-spin" /> : <ShieldCheck size={24} />}
              </button>
          </div>
          <div className={`p-4 rounded-full text-slate-300 transition-all duration-500 ${isExpanded ? 'rotate-180 text-indigo-500 bg-indigo-50' : ''}`}>
             <ChevronDown size={28} />
          </div>
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/30 p-10 pt-4 border-t border-slate-50 animate-in slide-in-from-top-6 duration-700">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-12">
            {/* AI Insights Panel */}
            <div className="lg:col-span-5 space-y-8">
              {detailedSummary && (
                <div className="bg-white p-10 rounded-[3.5rem] border border-indigo-100 shadow-2xl shadow-indigo-500/5 relative group/report animate-in zoom-in-95">
                  <div className="absolute top-8 left-8">
                     <button onClick={copyToClipboard} className="p-3 bg-slate-50 text-slate-400 hover:text-indigo-600 rounded-xl border border-slate-100 shadow-sm transition-all">
                        {copySuccess ? <Check size={20} className="text-emerald-500" /> : <Copy size={20} />}
                     </button>
                  </div>
                  <div className="flex items-center gap-5 mb-8">
                    <div className="p-4 bg-gradient-to-tr from-indigo-600 to-violet-500 text-white rounded-[1.75rem] shadow-xl shadow-indigo-500/20">
                      <Sparkles size={28} />
                    </div>
                    <div>
                       <h4 className="font-black text-lg text-slate-900 tracking-tight">التحليل الإداري الذكي</h4>
                       <p className="text-[10px] text-indigo-500 font-black uppercase tracking-[0.3em] mt-1">Generated by Gemini AI</p>
                    </div>
                  </div>
                  <div className="text-[13px] text-slate-700 leading-[1.8] whitespace-pre-line font-medium bg-[#fbfdff] p-8 rounded-[2.5rem] border border-indigo-50 shadow-inner">
                    {detailedSummary}
                  </div>
                  <button onClick={generateAIAudit} className="mt-6 w-full py-4 text-xs font-black text-indigo-600 hover:bg-indigo-50 rounded-2xl border border-dashed border-indigo-200 transition-all">
                    تحديث التحليل الذكي
                  </button>
                </div>
              )}

              {auditResult && (
                <div className={`p-8 rounded-[3rem] border text-sm font-black flex items-center gap-6 shadow-xl shadow-slate-200/10 animate-in slide-in-from-right-5 ${auditResult.includes('خلل') ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                   <div className={`p-4 rounded-[1.5rem] ${auditResult.includes('خلل') ? 'bg-rose-500 shadow-rose-200' : 'bg-emerald-500 shadow-emerald-200'} text-white shadow-lg`}>
                      <ShieldCheck size={28} />
                   </div>
                   <div className="flex flex-col gap-1">
                      <span className="opacity-50 uppercase tracking-[0.2em] text-[10px]">الملخص التقني</span>
                      <span className="text-base tracking-tight leading-tight">{auditResult}</span>
                   </div>
                </div>
              )}

              {!detailedSummary && !auditResult && !loadingSummary && !loadingAudit && (
                 <div className="text-center py-24 opacity-30 bg-white/50 rounded-[3.5rem] border border-dashed border-slate-200">
                    <BrainCircuit size={64} className="mx-auto mb-6 text-slate-300 animate-pulse" />
                    <p className="text-xs font-black uppercase tracking-[0.4em]">بانتظار تفعيل الذكاء الاصطناعي</p>
                 </div>
              )}
              {(loadingSummary || loadingAudit) && (
                <div className="text-center py-24 bg-white/50 rounded-[3.5rem] border border-slate-100">
                   <div className="w-12 h-12 border-4 border-indigo-100 border-t-indigo-600 rounded-full animate-spin mx-auto mb-6"></div>
                   <p className="text-xs font-black text-slate-400 tracking-widest uppercase">جاري التوليد الآن...</p>
                </div>
              )}
            </div>

            {/* Shifts History Panel */}
            <div className="lg:col-span-7 space-y-8">
              <div className="flex items-center gap-4 px-4">
                 <History size={20} className="text-slate-400" />
                 <span className="text-xs font-black text-slate-400 uppercase tracking-[0.4em]">التاريخ التفصيلي للنوبات</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {employee.shifts.map((shift, i) => <ShiftCard key={i} shift={shift} />)}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatMini = ({ label, value, icon }: any) => (
  <div className="text-center group flex flex-col items-center">
     <div className="flex items-center gap-2 mb-2 opacity-50 group-hover:opacity-100 transition-opacity">
        {icon}
        <span className="text-[10px] font-black text-slate-500 uppercase tracking-tighter">{label}</span>
     </div>
     <div className="text-xl font-black text-slate-900 group-hover:text-indigo-600 transition-colors">{value}</div>
  </div>
);

const ShiftCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';

  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  return (
    <div className={`p-8 rounded-[3.5rem] border bg-white flex flex-col transition-all duration-500 hover:shadow-2xl hover:-translate-y-2 ${isComplete ? 'border-slate-100 shadow-sm' : 'border-rose-100 bg-rose-50/10'}`}>
      <div className="flex items-center justify-between mb-8">
        <div className="flex items-center gap-4">
          <div className={`p-3.5 rounded-2xl shadow-sm ${isComplete ? 'bg-indigo-50 text-indigo-600' : 'bg-rose-50 text-rose-600'}`}>
            <Calendar size={20} />
          </div>
          <div>
             <span className="text-lg font-black text-slate-800 tracking-tight block leading-none">{shift.shift_date}</span>
             <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">تاريخ النوبة</span>
          </div>
        </div>
        <span className={`px-5 py-2.5 rounded-2xl text-[10px] font-black uppercase shadow-lg transition-all ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-5">
        {groupedPunches.map((group, idx) => {
          const type = group.period;
          const isMain = type === 'دخول صباحي' || type === 'بصمة خروج';
          return (
            <div key={idx} className={`relative py-5 px-6 rounded-[2rem] border transition-all ${
              type === 'بصمة خروج' ? 'bg-emerald-50/30 border-emerald-100/50' : 
              type === 'دخول صباحي' ? 'bg-indigo-50/30 border-indigo-100/50' : 'bg-slate-50/50 border-slate-100'
            }`}>
               <div className="flex items-center justify-between mb-3">
                  <span className={`text-[11px] font-black uppercase tracking-widest flex items-center gap-3 ${
                    type === 'بصمة خروج' ? 'text-emerald-700' : 
                    type === 'دخول صباحي' ? 'text-indigo-700' : 'text-slate-500'
                  }`}>
                    {type === 'بصمة خروج' ? <LogOut size={16} /> : type === 'دخول صباحي' ? <LogIn size={16} /> : <Clock size={16} />}
                    {type}
                  </span>
               </div>
               <div className="flex flex-wrap gap-2.5">
                 {group.punches.map((p, pIdx) => (
                   <span key={pIdx} className={`px-4 py-2 rounded-xl border text-[13px] font-black flex items-center gap-2.5 transition-all ${
                      p.is_duplicate ? 'bg-rose-50 border-rose-100 text-rose-300 line-through opacity-50' : 'bg-white border-slate-200 text-slate-700 shadow-sm'
                    }`}>
                     {p.time}
                   </span>
                 ))}
               </div>
            </div>
          );
        })}
        {!isComplete && (
           <div className="flex items-center gap-4 text-rose-500 text-[11px] font-black px-6 py-5 bg-rose-50/50 rounded-[2.25rem] border border-dashed border-rose-200">
              <ShieldAlert size={20} className="shrink-0" />
              <p>سجل غير مكتمل: يوجد فجوة زمنية لم يتم تسجيل البصمة فيها.</p>
           </div>
        )}
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

// وظيفة استخراج قائمة النواقص فقط - بدون تحليل
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
  const faultyShifts = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      const missing = required.filter(r => !present.includes(r));
      return { date: s.shift_date, missing };
    });

  if (faultyShifts.length === 0) return "✅ لا توجد نواقص في هذا السجل.";

  // إرسال البيانات المصفاة فقط لضمان دقة الاستخراج
  const dataString = faultyShifts.map(f => `${f.date}: ينقصه (${f.missing.join('، ')})`).join('\n');

  const prompt = `أنت محرك استخراج بيانات. استخرج قائمة النواقص للموظف (${employee.name}) من البيانات التالية بدقة:
  ${dataString}

  المطلوب منك فقط:
  سرد التواريخ والنواقص المقابلة لها في نقاط واضحة.
  ممنوع كتابة أي مقدمة، أو تحليل، أو توصيات، أو نصائح إدارية. 
  فقط القائمة المباشرة.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0.1, // تقليل العشوائية لضمان الدقة
        maxOutputTokens: 1000 
      }
    });
    return response.text?.trim() || "فشل في استخراج القائمة.";
  } catch (error) {
    console.error("AI Error:", error);
    return "⚠️ خطأ في الاتصال بالذكاء الاصطناعي.";
  }
};

// وظيفة تحليل النواقص العامة - تم تبسيطها لتكون تقرير نواقص إحصائي فقط
export const analyzeGlobalDeficienciesAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyEmployees = employees.filter(e => !e.isEligible);
  if (faultyEmployees.length === 0) return "✅ جميع الموظفين لديهم سجلات مكتملة.";

  const stats = {
    total: employees.length,
    faultyCount: faultyEmployees.length,
    commonIssues: {} as Record<string, number>
  };

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
  faultyEmployees.forEach(e => {
    e.shifts.filter(s => s.status === 'ناقصة').forEach(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      required.forEach(r => {
        if (!present.includes(r)) {
          stats.commonIssues[r] = (stats.commonIssues[r] || 0) + 1;
        }
      });
    });
  });

  const prompt = `أنت مدقق بيانات بصمة. اكتب كشفاً إحصائياً للنواقص المكتشفة بناءً على الإحصائيات التالية:
  - إجمالي الكادر: ${stats.total}
  - عدد الموظفين بنواقص: ${stats.faultyCount}
  - توزيع النواقص حسب الفترة: ${JSON.stringify(stats.commonIssues)}

  المطلوب: سرد الأرقام بوضوح، وتحديد أكثر فترة زمنية مفقودة في المؤسسة. لا تكتب أي تحليل أدبي أو نصائح.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 1000 }
    });
    return response.text?.trim() || "التقرير الإحصائي جاهز.";
  } catch (error) {
    return "⚠️ فشل الاستخراج الجماعي.";
  }
};

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const faultyDates = employee.shifts.filter(s => s.status === 'ناقصة').slice(0, 5).map(s => s.shift_date);
  if (faultyDates.length === 0) return "✅ سجل نظامي بالكامل.";

  const prompt = `دقق تقنياً: الموظف ${employee.name} لديه نواقص في التواريخ: ${faultyDates.join(',')}. هل تعتقد أن المشكلة تقنية في الجهاز؟ أجب باختصار شديد (نعم/لا/غير محدد) مع ذكر السبب في 5 كلمات.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 100 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle,
  FileSearch, BarChart3, Zap, ListChecks
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeGlobalDeficienciesAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [globalReport, setGlobalReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setGlobalReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateGlobalReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setGlobalReport(null);
    try {
      const result = await analyzeGlobalDeficienciesAI(employees);
      setGlobalReport(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 font-sans flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#050914] text-white transition-all duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="flex items-center gap-4 mb-12 group cursor-pointer">
            <div className="p-3 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-500/30 group-hover:rotate-12 transition-transform">
              <Zap size={24} className="text-white fill-current" />
            </div>
            <div>
              <h1 className="font-black text-xl text-white tracking-tight leading-none">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-1 opacity-70">نظام التدقيق الرقمي</p>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={20}/>} label="قاعدة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<ListChecks size={20}/>} label="تقرير النواقص" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto">
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-sm text-white shadow-xl shadow-indigo-600/20 active:scale-95 group">
              <FileUp size={20} className="group-hover:-translate-y-1 transition-transform" />
              <span>رفع ملف جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-100 px-8 py-5 flex items-center justify-between shrink-0 z-20">
          <div className="flex items-center gap-6 flex-1">
            <button className="lg:hidden p-2.5 text-slate-500 hover:bg-slate-50 rounded-xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={24} />
            </button>
            <div className="relative w-full max-w-lg group">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={18} />
              <input 
                type="text" 
                placeholder="ابحث بالاسم أو الرقم الوظيفي..." 
                className="w-full bg-slate-100/50 border border-slate-200 rounded-2xl pr-12 pl-5 py-3 text-sm outline-none focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-400 transition-all"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>
          <button 
            onClick={generateGlobalReport}
            disabled={employees.length === 0 || isAnalyzing}
            className="flex items-center gap-2.5 px-6 py-3 bg-slate-900 text-white rounded-xl text-xs font-black hover:bg-indigo-600 transition-all shadow-lg active:scale-95 disabled:opacity-30"
          >
            {isAnalyzing ? <RefreshCcw size={18} className="animate-spin" /> : <FileSearch size={18} />}
            <span>استخراج قائمة النواقص للكل</span>
          </button>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-10 space-y-10 bg-[#f8fafc] custom-scrollbar pb-40">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in duration-700 max-w-7xl mx-auto space-y-10">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <StatCard title="إجمالي الكادر" value={stats.totalEmployees} icon={<Users size={24}/>} color="indigo" />
                    <StatCard title="نسبة الانضباط" value={`${stats.completionRate}%`} icon={<Target size={24}/>} color="emerald" />
                    <StatCard title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={24}/>} color="amber" />
                  </div>
                  <SectionHeader icon={<Activity size={22}/>} title="الموظفون المكتشفون" subtitle="آخر الموظفين الذين تمت معالجة بياناتهم" />
                  <EmployeeListSection employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in duration-500 max-w-7xl mx-auto space-y-8">
              <SectionHeader icon={<Users size={22}/>} title="سجل الموظفين الشامل" subtitle={`إجمالي الموظفين: ${filteredEmployees.length}`} />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in zoom-in-95 duration-500 max-w-5xl mx-auto">
              <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden relative">
                <div className="p-12">
                   <div className="flex items-center gap-6 mb-10">
                      <div className="w-16 h-16 bg-indigo-50 rounded-2xl flex items-center justify-center border border-indigo-100">
                         <ListChecks size={32} className="text-indigo-600" />
                      </div>
                      <div>
                         <h2 className="text-2xl font-black text-slate-900">تقرير النواقص الموحد</h2>
                         <p className="text-slate-400 text-sm font-bold">كشف إحصائي بمناطق الخلل في المؤسسة</p>
                      </div>
                   </div>

                   <div className="bg-slate-50 rounded-[2.5rem] p-10 border border-slate-200 relative group">
                      {isAnalyzing ? (
                        <div className="py-20 flex flex-col items-center gap-6">
                           <RefreshCcw size={48} className="animate-spin text-indigo-600" />
                           <p className="text-slate-500 font-black tracking-widest uppercase text-xs">جاري استخراج البيانات من Gemini...</p>
                        </div>
                      ) : globalReport ? (
                        <div className="whitespace-pre-line text-lg text-slate-700 leading-relaxed font-bold">
                           {globalReport}
                        </div>
                      ) : (
                        <div className="py-20 text-center opacity-40 font-bold">لا توجد بيانات مستخرجة حالياً. اضغط على زر الاستخراج للبدء.</div>
                      )}
                   </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

