  const themes: any = {
    indigo: "from-indigo-600 to-indigo-700 shadow-indigo-100",
    emerald: "from-emerald-500 to-emerald-600 shadow-emerald-100",
    amber: "from-amber-500 to-orange-500 shadow-amber-100"
  };
  return (
    <div className={`bg-gradient-to-br ${themes[color]} p-8 rounded-[2.5rem] text-white shadow-xl relative overflow-hidden group border border-white/10`}>
       <div className="relative z-10 flex justify-between items-center">
          <div>
            <p className="text-[10px] font-black uppercase opacity-70 mb-1 tracking-widest">{title}</p>
            <h4 className="text-3xl font-black tracking-tight">{value}</h4>
          </div>
          <div className="p-4 bg-white/15 backdrop-blur-md rounded-2xl border border-white/20">
            {icon}
          </div>
       </div>
    </div>
  );
};

