        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50/50 rounded-[2rem] py-5 px-10 border border-slate-200/50 gap-6 shadow-inner">
          <StatMini label="بصمات" value={employee.totalPunches} icon={<Fingerprint size={12} className="text-amber-500"/>} />
          <StatMini label="نوبات" value={employee.shifts.length} icon={<Timer size={12} className="text-indigo-500"/>} />
          <StatMini label="أداء" value={`${employee.performanceScore}%`} icon={<TrendingUp size={12} className="text-violet-500"/>} />
          <StatMini label="اكتمال" value={`${employee.completionRate}%`} icon={<Target size={12} className="text-emerald-500"/>} />
