        <div className="flex items-center gap-4">
          <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm">
             <button 
                onClick={getMissingList} 
                disabled={loadingSummary} 
                className={`flex items-center justify-center w-12 h-12 rounded-xl transition-all active:scale-90 disabled:opacity-40 ${detailedSummary ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400 hover:text-indigo-600'}`}
                title="كشف النواقص المستخرج"
              >
                {loadingSummary ? <RefreshCcw size={18} className="animate-spin" /> : <ClipboardList size={22} />}
              </button>
              <button 
                onClick={runSmartAudit} 
                disabled={loadingAudit} 
                className="flex items-center justify-center w-12 h-12 rounded-xl hover:bg-slate-900 hover:text-white text-slate-400 transition-all active:scale-90 disabled:opacity-40"
                title="تدقيق تقني"
              >
                {loadingAudit ? <RefreshCcw size={18} className="animate-spin" /> : <ShieldCheck size={22} />}
              </button>
          </div>
          <ChevronDown size={24} className={`text-slate-300 transition-all duration-500 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} />
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/30 p-8 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            <div className="lg:col-span-5 space-y-6">
              {detailedSummary && (
                <div className="bg-white p-8 rounded-[2.5rem] border border-indigo-100 shadow-xl relative animate-in zoom-in-95">
                  <div className="flex items-center gap-4 mb-6">
                    <div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg">
                      <ListChecks size={20} />
