import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

// وظيفة استخراج قائمة البصمات المفقودة فقط لكل تاريخ - دقة متناهية
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];

  // تصفية النوبات الناقصة فقط واستخراج المفقود منها برمجياً لضمان الدقة قبل الإرسال
  const faultyShifts = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      const missing = required.filter(r => !present.includes(r));
      return { date: s.shift_date, missing };
    });

  if (faultyShifts.length === 0) return "✅ لا توجد بصمات مفقودة في السجل.";

  // تجهيز البيانات الخام لإرسالها للمحرك
  const rawData = faultyShifts.map(f => `${f.date}: ${f.missing.join('، ')}`).join('\n');

  const prompt = `أنت محرك تنسيق بيانات بصمة. قم بصياغة البيانات التالية في قائمة نقطية مرتبة:
  البيانات:
  ${rawData}

  القوانين الصارمة:
  1. اذكر التاريخ ثم اسم البصمة الناقصة فقط (مثال: 2025-08-20: بصمة وسطية).
  2. ممنوع تماماً كتابة كلمة "ينقصه" أو "مفقود" أو أي مقدمات.
  3. لا تذكر أي نوبة مكتملة.
  4. لا تقم بأي تحليل أو إعطاء نصائح.
  5. اخرج القائمة فقط بشكل مباشر ومجرد.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { 
        temperature: 0, // لضمان عدم وجود أي إبداع لغوي خارج المطلوب
        maxOutputTokens: 1000 
      }
    });
    return response.text?.trim() || "فشل استخراج قائمة النواقص.";
  } catch (error) {
    console.error("AI Error:", error);
    return "⚠️ خطأ فني في استخراج النواقص.";
  }
};

// وظيفة تحليل النواقص العامة - كشف إحصائي جاف ومباشر
export const analyzeGlobalDeficienciesAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyEmployees = employees.filter(e => !e.isEligible);
  if (faultyEmployees.length === 0) return "✅ كافة السجلات مكتملة ونظامية.";

  const stats = {
    total: employees.length,
    faultyCount: faultyEmployees.length,
    commonIssues: {} as Record<string, number>
  };

  const required = ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"];
  faultyEmployees.forEach(e => {
    e.shifts.filter(s => s.status === 'ناقصة').forEach(s => {
      const present = s.punches_details.filter(p => !p.is_duplicate).map(p => p.period);
      required.forEach(r => {
        if (!present.includes(r)) {
          stats.commonIssues[r] = (stats.commonIssues[r] || 0) + 1;
        }
      });
    });
  });

  const prompt = `اكتب ملخصاً إحصائياً (أرقام فقط) للنواقص التالية:
  - إجمالي الموظفين: ${stats.total}
  - الموظفين الذين لديهم نقص: ${stats.faultyCount}
  - تفصيل النواقص: ${JSON.stringify(stats.commonIssues)}

  المطلوب: اذكر الأرقام ونوع البصمة الأكثر نقصاً فقط. بدون أي تحليل إداري.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 500 }
    });
    return response.text?.trim() || "التقرير الإحصائي جاهز.";
  } catch (error) {
    return "⚠️ تعذر استخراج الإحصائيات العامة.";
  }
};

export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const faultyDates = employee.shifts.filter(s => s.status === 'ناقصة').slice(0, 3).map(s => s.shift_date);

  const prompt = `دقق تقنياً: ID ${employee.id} لديه نقص في ${faultyDates.join(',')}. هل السلوك بشري أم تقني؟ رد بكلمتين فقط.`;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0, maxOutputTokens: 50 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

import React, { useState, useMemo } from 'react';
