              <Zap size={24} className="text-white fill-current" />
            </div>
            <div>
              <h1 className="font-black text-xl text-white tracking-tight leading-none">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[10px] text-slate-500 font-black uppercase tracking-[0.2em] mt-1 opacity-70">نظام التدقيق الرقمي</p>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={20}/>} label="قاعدة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<ListChecks size={20}/>} label="كشف النواقص" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto">
            <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-black text-sm text-white shadow-xl shadow-indigo-600/20 active:scale-95 group">
              <FileUp size={20} className="group-hover:-translate-y-1 transition-transform" />
              <span>رفع ملف جديد</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-100 px-8 py-5 flex items-center justify-between shrink-0 z-20">
