          {currentView === 'integrity' && (
            <div className="animate-in fade-in zoom-in-95 duration-500 max-w-5xl mx-auto">
              <div className="bg-white rounded-[3.5rem] shadow-2xl border border-slate-100 overflow-hidden relative">
