      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const getMissingList = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    setDetailedSummary(null);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
      setIsExpanded(true);
    } catch (err) {
      setDetailedSummary("⚠️ فشل استخراج القائمة.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const isAllComplete = employee.isEligible;

  return (
    <div className={`bg-white rounded-[2.5rem] transition-all duration-500 overflow-hidden group/main ${isExpanded ? 'shadow-2xl ring-4 ring-indigo-50 border-transparent' : 'shadow-sm border border-slate-100 hover:border-indigo-100'}`}>
      <div 
        className={`p-6 flex flex-col lg:flex-row items-center gap-8 cursor-pointer relative transition-all duration-500 ${isAllComplete ? 'bg-gradient-to-l from-emerald-50/10' : 'bg-gradient-to-l from-rose-50/10'}`} 
        onClick={() => setIsExpanded(!isExpanded)}
      >
        <div className="flex items-center gap-5 min-w-[340px]">
          <div className={`w-16 h-16 rounded-2xl flex items-center justify-center font-black text-2xl shadow-xl ${isAllComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
            {employee.name.charAt(0)}
          </div>
          <div>
            <h3 className="font-black text-xl text-slate-900 truncate max-w-[240px] leading-tight">{employee.name}</h3>
            <div className="flex items-center gap-2.5 mt-1">
              <span className="text-[10px] font-black text-slate-400 bg-slate-100 px-2.5 py-1 rounded-xl uppercase tracking-widest">ID: {employee.id}</span>
              <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase tracking-widest border ${employee.isEligible ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                {employee.isEligible ? 'نظامي' : 'يوجد نواقص'}
              </span>
            </div>
          </div>
        </div>

        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50/50 rounded-[2rem] py-5 px-10 border border-slate-200/50 gap-6 shadow-inner">
          <StatMini label="بصمات" value={employee.totalPunches} icon={<Fingerprint size={12} className="text-amber-500"/>} />
          <StatMini label="نوبات" value={employee.shifts.length} icon={<Timer size={12} className="text-indigo-500"/>} />
          <StatMini label="أداء" value={`${employee.performanceScore}%`} icon={<TrendingUp size={12} className="text-violet-500"/>} />
          <StatMini label="اكتمال" value={`${employee.completionRate}%`} icon={<Target size={12} className="text-emerald-500"/>} />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex bg-white p-1.5 rounded-2xl border border-slate-100 shadow-sm">
             <button 
                onClick={getMissingList} 
                disabled={loadingSummary} 
                className={`flex items-center justify-center w-12 h-12 rounded-xl transition-all active:scale-90 disabled:opacity-40 ${detailedSummary ? 'bg-indigo-600 text-white' : 'bg-slate-50 text-slate-400 hover:text-indigo-600'}`}
                title="كشف البصمات المفقودة"
              >
                {loadingSummary ? <RefreshCcw size={18} className="animate-spin" /> : <ClipboardList size={22} />}
              </button>
              <button 
                onClick={runSmartAudit} 
                disabled={loadingAudit} 
                className="flex items-center justify-center w-12 h-12 rounded-xl hover:bg-slate-900 hover:text-white text-slate-400 transition-all active:scale-90 disabled:opacity-40"
                title="تدقيق تقني"
              >
                {loadingAudit ? <RefreshCcw size={18} className="animate-spin" /> : <ShieldCheck size={22} />}
              </button>
          </div>
          <ChevronDown size={24} className={`text-slate-300 transition-all duration-500 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} />
        </div>
      </div>

      {isExpanded && (
        <div className="bg-slate-50/30 p-8 pt-4 border-t border-slate-50 animate-in slide-in-from-top-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            <div className="lg:col-span-5 space-y-6">
              {detailedSummary && (
                <div className="bg-white p-8 rounded-[2.5rem] border border-indigo-100 shadow-xl relative animate-in zoom-in-95">
                  <div className="flex items-center gap-4 mb-6">
                    <div className="p-3 bg-indigo-600 text-white rounded-xl shadow-lg">
                      <ListChecks size={20} />
                    </div>
                    <div>
                       <h4 className="font-black text-sm text-slate-900 block tracking-tight">كشف البصمات المفقودة</h4>
                       <p className="text-[9px] text-indigo-500 font-black uppercase tracking-widest">مستخرج من Gemini AI</p>
                    </div>
                  </div>
                  <div className="text-[13px] text-slate-700 leading-relaxed whitespace-pre-line font-bold bg-[#fbfdff] p-6 rounded-2xl border border-indigo-50 shadow-inner">
                    {detailedSummary}
                  </div>
                </div>
              )}

              {auditResult && (
                <div className={`p-6 rounded-3xl border text-xs font-black flex items-center gap-5 shadow-lg ${auditResult.includes('نعم') ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                   <ShieldCheck size={24} className={auditResult.includes('نعم') ? 'text-rose-500' : 'text-emerald-500'} />
                   <div className="flex flex-col">
                      <span className="opacity-50 uppercase tracking-widest text-[9px]">التدقيق التقني</span>
                      <span className="text-sm tracking-tight">{auditResult}</span>
                   </div>
                </div>
              )}
            </div>

            <div className="lg:col-span-7 space-y-6">
              <div className="flex items-center gap-3 px-2">
                 <History size={16} className="text-slate-400" />
                 <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تاريخ النوبات</span>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {employee.shifts.map((shift, i) => <ShiftCard key={i} shift={shift} />)}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatMini = ({ label, value, icon }: any) => (
  <div className="text-center">
     <div className="flex items-center justify-center gap-1.5 mb-1 opacity-50">
        {icon}
        <span className="text-[9px] font-black text-slate-500 uppercase tracking-tighter">{label}</span>
     </div>
     <div className="text-lg font-black text-slate-900">{value}</div>
  </div>
);

const ShiftCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  return (
    <div className={`p-6 rounded-[2rem] border bg-white flex flex-col transition-all ${isComplete ? 'border-slate-100' : 'border-rose-100 bg-rose-50/10 shadow-sm'}`}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <Calendar size={18} className={isComplete ? 'text-indigo-600' : 'text-rose-600'} />
          <span className="text-sm font-black text-slate-800 tracking-tight">{shift.shift_date}</span>
        </div>
        <span className={`px-3 py-1 rounded-xl text-[9px] font-black uppercase ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </span>
      </div>
      <div className="space-y-3">
        {groupedPunches.map((group, idx) => (
          <div key={idx} className="bg-slate-50/50 p-4 rounded-2xl border border-slate-100">
             <div className="text-[10px] font-black text-slate-400 uppercase mb-2 tracking-widest">{group.period}</div>
             <div className="flex flex-wrap gap-2">
               {group.punches.map((p, pIdx) => (
                 <span key={pIdx} className={`px-3 py-1.5 rounded-lg border text-[12px] font-black ${
                    p.is_duplicate ? 'bg-rose-50 text-rose-300 border-rose-100 line-through' : 'bg-white text-slate-700 shadow-xs'
                  }`}>
                   {p.time}
                 </span>
               ))}
             </div>
          </div>
        ))}
        {!isComplete && (
           <div className="flex items-center gap-3 text-rose-500 text-[10px] font-black px-4 py-3 bg-rose-50 rounded-xl border border-dashed border-rose-200">
              <ShieldAlert size={16} />
              <span>يوجد فجوة في تسلسل البصمة</span>
           </div>
        )}
      </div>
    </div>
  );
};

export default App;
